import{_ as a,o as t,c as o,ag as d}from"./chunks/framework.Buu0rXrd.js";const h=JSON.parse('{"title":"歌词格式与返回键","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/presentation.md","filePath":"plugins/presentation.md"}'),r={name:"plugins/presentation.md"};function c(i,e,n,s,l,_){return t(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="歌词格式与返回键" tabindex="-1">歌词格式与返回键 <a class="header-anchor" href="#歌词格式与返回键" aria-label="Permalink to &quot;歌词格式与返回键&quot;">​</a></h1><h2 id="歌词格式-30" tabindex="-1">歌词格式（30） <a class="header-anchor" href="#歌词格式-30" aria-label="Permalink to &quot;歌词格式（30）&quot;">​</a></h2><p><code>type = &quot;lyric-source&quot;</code> 的选中实现可在 <code>query_interface</code> 返回 <code>LyraLyricFormatV3</code>。转换与 <code>supply</code> 独立。只提供转换时，宿主仍负责读取原始歌词。</p><table tabindex="0"><thead><tr><th>操作</th><th>输入</th><th>成功回复</th></tr></thead><tbody><tr><td><code>LYRA_LYRIC_NORMALIZE</code></td><td><code>LYRA_LYRIC_INPUT</code>，BYTES</td><td><code>LYRA_LYRIC_OUTPUT</code>，BYTES</td></tr></tbody></table><p>输出为默认歌词解析器支持的 UTF-8 歌词文本，不带 NUL。空输出清除歌词，<code>UNSUPPORTED</code> 交回宿主处理原始输入。回调在帧线程同步执行，每条消息最多 1 MiB。返回后宿主立即复制数据。此接口处理播放歌词，本地后台全库索引仍使用内置解析。需要独立索引时使用<a href="/LyraPlayer-docs-site/plugins/media#替换默认搜索与本地来源">搜索提供者</a>。</p><h2 id="根返回键-29" tabindex="-1">根返回键（29） <a class="header-anchor" href="#根返回键-29" aria-label="Permalink to &quot;根返回键（29）&quot;">​</a></h2><p><code>type = &quot;frame&quot;</code> 的选中实现可提供 <code>LyraNavigationV3</code>。</p><ul><li><code>LYRA_NAVIGATION_BACK_AVAILABLE</code> 查询能否消费 Back。可处理时返回 <code>OK</code>，其余情况返回 <code>UNSUPPORTED</code>。查询不改变页面。</li><li><code>LYRA_NAVIGATION_BACK</code> 执行返回操作，消费后返回 <code>OK</code>。</li><li>两种消息都不带字段。可用状态变化后调用 <code>host-&gt;request_frame</code>，宿主在帧上同步 Android 返回拦截。</li></ul><p>独立根负责场景、触摸和帧请求。保留默认页面时，使用 <a href="/LyraPlayer-docs-site/plugins/service-context">服务上下文</a> 显式委托。没有 Back 端点时由系统处理返回。</p><p><a href="/LyraPlayer-docs-site/downloads/sdk/include/plugin/lyric_format_contracts.h">歌词格式头文件</a> · <a href="/LyraPlayer-docs-site/downloads/sdk/include/plugin/navigation_contracts.h">导航头文件</a></p>',10)])])}const u=a(r,[["render",c]]);export{h as __pageData,u as default};
